package zw.ac.msu.dzimbahub.payment;

import org.springframework.beans.factory.annotation.Value;
import org.springframework.http.*;
import org.springframework.security.core.Authentication;
import org.springframework.transaction.annotation.Transactional;
import org.springframework.web.bind.annotation.*;
import org.springframework.web.server.ResponseStatusException;
import zw.ac.msu.dzimbahub.auth.*;
import zw.ac.msu.dzimbahub.model.Property;
import zw.ac.msu.dzimbahub.repository.PropertyRepository;
import zw.co.paynow.core.Paynow;
import zw.co.paynow.core.Payment;
import zw.co.paynow.core.WebInitResponse;
import zw.co.paynow.core.StatusResponse;
import java.time.Instant;
import java.util.*;

@RestController @RequestMapping("/api/payments")
public class PaymentController {
 private final PaymentRepository payments; private final PropertyRepository properties; private final AppUserRepository users;
 @Value("${paynow.integration-id:}") private String integrationId;
 @Value("${paynow.integration-key:}") private String integrationKey;
 @Value("${APP_FRONTEND_URL:http://localhost:3000}") private String frontendUrl;
 public PaymentController(PaymentRepository p,PropertyRepository r,AppUserRepository u){payments=p;properties=r;users=u;}
 public record StartRequest(Long propertyId,String method,String phone,String externalReference,String proofNote){}
 private AppUser current(Authentication a){if(a==null)throw new ResponseStatusException(HttpStatus.UNAUTHORIZED,"Sign in first.");return users.findByEmailIgnoreCase(a.getName()).orElseThrow(()->new ResponseStatusException(HttpStatus.UNAUTHORIZED));}
 private AppUser tenant(Authentication a){AppUser u=current(a);if(u.getRole()!=UserRole.TENANT)throw new ResponseStatusException(HttpStatus.FORBIDDEN,"Only tenants can make rental payments.");return u;}
 private Map<String,Object> dto(PaymentRecord p){Map<String,Object> m=new LinkedHashMap<>();m.put("id",p.getId());m.put("merchantReference",p.getMerchantReference());m.put("propertyId",p.getPropertyId());m.put("propertyTitle",p.getPropertyTitle());m.put("amount",p.getAmount());m.put("method",p.getMethod());m.put("status",p.getStatus());m.put("tenantEmail",p.getTenantEmail());m.put("landlordEmail",p.getLandlordEmail());m.put("externalReference",p.getExternalReference());m.put("paynowReference",p.getPaynowReference());m.put("instructions",p.getInstructions());m.put("createdAt",p.getCreatedAt());m.put("paidAt",p.getPaidAt());m.put("checkoutUrl",p.getCheckoutUrl());m.put("receiptNumber",p.getStatus().equals("PAID")?"DZH-"+p.getId():null);return m;}
 @PostMapping("/start") public ResponseEntity<?> start(@RequestBody StartRequest r,Authentication a){AppUser t=tenant(a);if(r.propertyId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Choose a property.");Property p=properties.findById(r.propertyId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Property not found."));if(p.isRented())throw new ResponseStatusException(HttpStatus.CONFLICT,"This property is no longer available.");if(p.getLandlordId()==null)throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This demo listing has no linked landlord account and cannot accept payment.");AppUser l=users.findById(p.getLandlordId()).orElseThrow(()->new ResponseStatusException(HttpStatus.CONFLICT,"The landlord account is unavailable."));String method=r.method()==null?"":r.method().trim().toUpperCase(Locale.ROOT);if(!List.of("PAYNOW","CASH","BANK_TRANSFER","INNBUCKS","ECOCASH_MANUAL").contains(method))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Unsupported payment method.");String ref="DZH"+UUID.randomUUID().toString().replace("-","").substring(0,20).toUpperCase(Locale.ROOT);PaymentRecord record=new PaymentRecord(ref,p.getId(),t.getId(),l.getId(),t.getEmail(),l.getEmail(),p.getTitle(),p.getPrice(),method);record.setExternalReference(clean(r.externalReference(),150));record.setInstructions(clean(r.proofNote(),1500));
  if(method.equals("PAYNOW")){if(integrationId.isBlank()||integrationKey.isBlank())throw new ResponseStatusException(HttpStatus.SERVICE_UNAVAILABLE,"Paynow credentials are not configured. Set PAYNOW_INTEGRATION_ID and PAYNOW_INTEGRATION_KEY in the backend environment.");try{Paynow paynow=new Paynow(integrationId,integrationKey);paynow.setResultUrl(baseApi()+"/payments/paynow-result");paynow.setReturnUrl(frontendUrl.replaceAll("/$","")+"/payments/return?reference="+ref);Payment payment=paynow.createPayment(ref,t.getEmail());payment.add("First month rent - "+p.getTitle(),p.getPrice());WebInitResponse response=paynow.send(payment);if(!response.isRequestSuccess())throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Paynow could not start the payment. Please try again.");record.setCheckoutUrl(response.redirectURL());record.setPollUrl(response.pollUrl());record.setInstructions("Complete payment on Paynow. The listing is reserved only after Paynow confirms payment.");}catch(ResponseStatusException e){throw e;}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Unable to connect to Paynow. Please try again.");}}
  else {if(record.getExternalReference()==null||record.getExternalReference().isBlank())throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Enter the transfer / wallet reference or cash receipt number. The landlord must verify this payment.");record.setInstructions((record.getInstructions()==null?"":record.getInstructions()+" ")+"Submitted for landlord verification. This does not mark the property as paid until the landlord confirms receipt.");}
  payments.save(record);return ResponseEntity.status(HttpStatus.CREATED).body(dto(record)); }
 private String baseApi(){return System.getenv().getOrDefault("PUBLIC_API_URL","").replaceAll("/$","")+"/api";}
 private String clean(String s,int max){if(s==null)return null;String x=s.trim();return x.isEmpty()?null:x.substring(0,Math.min(max,x.length()));}
 @PostMapping("/paynow-result") @Transactional public ResponseEntity<?> paynowResult(@RequestParam Map<String,String> form){String ref=form.getOrDefault("reference","");if(ref.isBlank())return ResponseEntity.badRequest().build();PaymentRecord p=payments.findByMerchantReference(ref).orElse(null);if(p==null)return ResponseEntity.ok().build();if(form.containsKey("paynowreference"))p.setPaynowReference(clean(form.get("paynowreference"),100));payments.save(p); // Confirm with Paynow's poll URL; never trust the browser redirect or callback status alone.
  if(p.getPollUrl()!=null&&!p.getPollUrl().isBlank()&&!p.getStatus().equals("PAID")){try{Paynow paynow=new Paynow(integrationId,integrationKey);StatusResponse status=paynow.pollTransaction(p.getPollUrl());if(status.paid())markPaid(p);}catch(Exception ignored){/* Tenant can retry verification from the return page or dashboard. */}}return ResponseEntity.ok().build();}
 @PostMapping("/{reference}/verify") @Transactional public Map<String,Object> verify(@PathVariable String reference,Authentication a){AppUser t=tenant(a);PaymentRecord p=payments.findByMerchantReference(reference).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!Objects.equals(p.getTenantId(),t.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(!p.getMethod().equals("PAYNOW")&&!p.getMethod().equals("ECOCASH_MANUAL"))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"This payment is verified by the landlord.");if(!p.getStatus().equals("PAID")){if(p.getPollUrl()==null||p.getPollUrl().isBlank())throw new ResponseStatusException(HttpStatus.CONFLICT,"Paynow status is not available yet.");try{Paynow paynow=new Paynow(integrationId,integrationKey);StatusResponse status=paynow.pollTransaction(p.getPollUrl());if(status.paid()){markPaid(p);}else{p.setStatus("PENDING");payments.save(p);}}catch(Exception e){throw new ResponseStatusException(HttpStatus.BAD_GATEWAY,"Could not verify payment with Paynow yet. Retry in a moment.");}}return dto(p);}
 private void markPaid(PaymentRecord p){Property property=properties.findById(p.getPropertyId()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(property.isRented()&&!p.getStatus().equals("PAID")){p.setStatus("CONFLICT");payments.save(p);throw new ResponseStatusException(HttpStatus.CONFLICT,"This property was already paid for by another tenant. Contact support.");}property.setRented(true);properties.save(property);p.setStatus("PAID");p.setPaidAt(Instant.now());payments.save(p);}
 @GetMapping("/mine") public List<Map<String,Object>> mine(Authentication a){AppUser u=current(a);if(u.getRole()!=UserRole.TENANT)throw new ResponseStatusException(HttpStatus.FORBIDDEN);return payments.findByTenantIdOrderByCreatedAtDesc(u.getId()).stream().map(this::dto).toList();}
 @GetMapping("/landlord/inbox") public List<Map<String,Object>> landlordInbox(Authentication a){AppUser u=current(a);if(u.getRole()!=UserRole.LANDLORD)throw new ResponseStatusException(HttpStatus.FORBIDDEN);return payments.findByLandlordIdOrderByCreatedAtDesc(u.getId()).stream().map(this::dto).toList();}
 @PutMapping("/{id}/confirm-manual") @Transactional public Map<String,Object> confirmManual(@PathVariable Long id,Authentication a){AppUser l=current(a);if(l.getRole()!=UserRole.LANDLORD)throw new ResponseStatusException(HttpStatus.FORBIDDEN);PaymentRecord p=payments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!Objects.equals(p.getLandlordId(),l.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN,"This payment belongs to another landlord.");if(!List.of("CASH","BANK_TRANSFER","INNBUCKS","ECOCASH_MANUAL").contains(p.getMethod()))throw new ResponseStatusException(HttpStatus.BAD_REQUEST,"Only manually verified methods can be confirmed here.");if(p.getStatus().equals("PAID"))return dto(p);if(p.getStatus().equals("PENDING")){markPaid(p);}return dto(p);}
 @PutMapping("/{id}/reject-manual") public Map<String,Object> rejectManual(@PathVariable Long id,Authentication a){AppUser l=current(a);if(l.getRole()!=UserRole.LANDLORD)throw new ResponseStatusException(HttpStatus.FORBIDDEN);PaymentRecord p=payments.findById(id).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!Objects.equals(p.getLandlordId(),l.getId()))throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(!p.getStatus().equals("PAID")){p.setStatus("REJECTED");payments.save(p);}return dto(p);}
 @GetMapping("/{reference}/receipt") public Map<String,Object> receipt(@PathVariable String reference,Authentication a){AppUser u=current(a);PaymentRecord p=payments.findByMerchantReference(reference).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND));if(!Objects.equals(u.getId(),p.getTenantId())&&!Objects.equals(u.getId(),p.getLandlordId())&&u.getRole()!=UserRole.ADMIN)throw new ResponseStatusException(HttpStatus.FORBIDDEN);if(!p.getStatus().equals("PAID"))throw new ResponseStatusException(HttpStatus.CONFLICT,"A receipt is available only after payment is confirmed.");return dto(p);}
}
